import axios from 'axios';
import { API_CONFIG } from '@/config/config';
import {  ElMessage } from 'element-plus';

export const chatModule = {
  namespaced: true,
  state: {
    recentChats: [],    // 所有最近聊天（按时间排序）
    recentGroups: [],   // 最近群聊
    recentUsers: [],    // 最近单聊
    joinedGroups: []    // 已加入的群聊列表
  },
  mutations: {
    // 添加或更新最近聊天（自动区分群聊和单聊）
    ADD_RECENT_CHAT(state, chat) {
      // 确保chat对象有id属性
      const chatId = chat.id || chat.group_id || chat.target_id;
      if (!chatId) {
        console.error('ADD_RECENT_CHAT错误：缺少有效的ID', chat);
        return;
      }
      
      const chatIdStr = chatId.toString();
      const isGroup = chat.isGroup === true;
      
      const targetList = isGroup ? state.recentGroups : state.recentUsers;
      
      // 查找现有记录
      const existingIndex = targetList.findIndex(item => item.id.toString() === chatIdStr);
      const existingChat = existingIndex !== -1 ? targetList[existingIndex] : null;
      
      // 合并数据策略
      let mergedChat = { ...chat, id: chatIdStr };
      
      // 对于群聊，优先使用joinedGroups中的完整信息
      if (isGroup) {
        const joinedGroup = state.joinedGroups.find(g => g.id.toString() === chatIdStr);
        if (joinedGroup) {
          mergedChat = {
            ...joinedGroup,
            ...mergedChat,
            // 保留关键时间信息
            lastMessage: mergedChat.lastMessage || joinedGroup.lastMessage,
            lastMessageTime: mergedChat.lastMessageTime || joinedGroup.lastMessageTime,
            // 保留未读计数
            unreadCount: mergedChat.unreadCount ?? joinedGroup.unreadCount
          };
        }
      }
      
      // 保留现有聊天的重要信息（如果存在）
      if (existingChat) {
        mergedChat = {
          ...existingChat,
          ...mergedChat,
          // 保留关键时间信息
          lastMessage: mergedChat.lastMessage || existingChat.lastMessage,
          lastMessageTime: mergedChat.lastMessageTime || existingChat.lastMessageTime
        };
        
        // 移除旧记录
        targetList.splice(existingIndex, 1);
      }
      
      // 添加到列表开头
      targetList.unshift(mergedChat);
      
      // 限制列表长度
      if (targetList.length > 50) {
        targetList.pop();
      }
      
      updateCombinedChats(state);
    },
    
    // 初始化最近聊天
    INIT_RECENT_CHATS(state, chats) {
      const normalizedChats = chats.map(chat => {
        // 确保chat对象有id属性
        const id = chat.id || chat.group_id || chat.target_id;
        if (!id) {
          console.error('INIT_RECENT_CHATS错误：缺少有效的ID', chat);
          return null;
        }
        
        return {
          ...chat,
          id: id.toString(), // 统一转为字符串
        };
      }).filter(chat => chat !== null); // 过滤掉无效的chat
      
      const groups = normalizedChats.filter(chat => chat.isGroup === true);
      const users = normalizedChats.filter(chat => chat.isGroup !== true);
      
      state.recentGroups = groups;
      state.recentUsers = users;
      
      updateCombinedChats(state);
    },
    
    // 初始化已加入的群聊
    INIT_JOINED_GROUPS(state, groups) {
      console.log("初始化群组数据:", groups);
      state.joinedGroups = (groups || []).map(group => {
        // 确保group对象有id属性
        const id = group.id || group.group_id || group.target_id;
        if (!id) {
          console.error('INIT_JOINED_GROUPS错误：缺少有效的ID', group);
          return null;
        }
        
        return {
          ...group,
          id: id.toString(), // 保持原始ID为字符串
          isGroup: true,
          members: Array.isArray(group.members) ? [...new Set(group.members)] : [],
          membersCount: group.membersCount
        };
      }).filter(group => group !== null); // 过滤掉无效的group
      
      console.log("处理后的群组数据:", state.joinedGroups);
    },
    
    // 更新单个群聊信息（不自动添加到最近聊天）
    UPDATE_JOINED_GROUP(state, updatedGroup) {
      // 确保updatedGroup对象有id属性
      const groupId = updatedGroup.id || updatedGroup.group_id || updatedGroup.target_id;
      if (!groupId) {
        console.error('UPDATE_JOINED_GROUP错误：缺少有效的ID', updatedGroup);
        return;
      }
      
      const groupIdStr = groupId.toString();
      const index = state.joinedGroups.findIndex(g => g.id.toString() === groupIdStr);
      
      if (index !== -1) {
        state.joinedGroups.splice(index, 1, { 
          ...state.joinedGroups[index], 
          ...updatedGroup,
          id: state.joinedGroups[index].id // 保持原始ID不变
        });
      } else {
        state.joinedGroups.push({ 
          ...updatedGroup, 
          id: groupIdStr, 
          isGroup: true
        });
      }
    },
    
    // 更新未读计数
    UPDATE_UNREAD_COUNT(state, { targetId, count }) {
      const targetIdStr = targetId.toString();
      
      // 更新最近聊天列表
      const updateChatList = (list) => {
        const index = list.findIndex(item => item.id.toString() === targetIdStr);
        if (index !== -1) {
          list[index].unreadCount = count;
        }
      };
      
      updateChatList(state.recentGroups);
      updateChatList(state.recentUsers);
      
      // 更新已加入的群聊列表
      const groupIndex = state.joinedGroups.findIndex(g => g.id.toString() === targetIdStr);
      if (groupIndex !== -1) {
        state.joinedGroups[groupIndex].unreadCount = count;
      }
    },
    
    // 清除所有聊天记录
    CLEAR_ALL_CHATS(state) {
      state.recentChats = [];
      state.recentGroups = [];
      state.recentUsers = [];
      state.joinedGroups = [];
    }
  },
  actions: {
    // 获取群头像
    async fetchGroupAvatar({ rootState }, groupId) {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/group/get-group-avatar/${groupId}`, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        return response.data || [];
      } catch (error) {
        console.error('获取群头像失败:', error);
        return [];
      }
    },

    // 加载最近聊天列表
    async loadRecentChats({ commit, dispatch, rootState }) {
      try {
        const userId = rootState.user.id;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/ws/chat/recent-chats/${userId}`, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        console.log("加载最近聊天：", response.data);
        
        // 并行获取所有群聊的头像
        const chatsWithAvatars = await Promise.all(
          (response.data || []).map(async chat => {
            if (!chat.is_group) return chat;
            
            // 确保chat对象有有效的id
            const groupId = chat.target_id || chat.group_id || chat.id;
            if (!groupId) {
              console.error('loadRecentChats错误：群聊缺少有效的ID', chat);
              return chat;
            }
            
            console.log("获取最近群聊天: ", chat);
            const avatarMembers = await dispatch('fetchGroupAvatar', groupId);
            return {
              ...chat,
              avatarMembers // 添加头像成员列表
            };
          })
        );
        
        const formattedChats = chatsWithAvatars.map(chat => {
          // 确保chat对象有有效的id
          const id = chat.target_id || chat.group_id || chat.id;
          if (!id) {
            console.error('loadRecentChats错误：聊天记录缺少有效的ID', chat);
            return null;
          }
          
          return {
            id: id.toString(),
            username: chat.target_username || chat.group_name,
            photo: chat.target_photo,
            lastMessage: chat.last_message,
            lastMessageTime: chat.last_message_time,
            unreadCount: chat.unread_count || 0,
            isGroup: chat.is_group || false,
            members_count: chat?.members_count || 0,
            group_members: chat?.group_members || [],
            group_owner_id: chat?.group_owner_id,
            avatar_members: chat.avatarMembers || [] // 确保有avatarMembers字段
          };
        }).filter(chat => chat !== null); // 过滤掉无效的chat
        
        console.log("chat的值： ", chatsWithAvatars);
        commit('INIT_RECENT_CHATS', formattedChats);
        return formattedChats;
      } catch (error) {
        console.error('加载最近聊天列表失败:', error);
        return [];
      }
    },

    // 修改loadJoinedGroups和loadRecentChats，添加头像获取
    async loadJoinedGroups({ commit, dispatch, rootState }) {
      try {
        if (!rootState.user?.id) {
          console.log('用户未登录，无法加载已加入的群聊');
          return [];
        }
        
        const response = await axios.get(
          `${API_CONFIG.BASE_URL}/group/get-joined-groups/${rootState.user.id}`,
          { headers: { Authorization: `Bearer ${rootState.token}` } }
        );
        
        // 并行获取所有群的头像
        const groupsWithAvatars = await Promise.all(
          (response.data || []).map(async group => {
            // 确保group对象有有效的id
            const groupId = group.group_id || group.id || group.target_id;
            if (!groupId) {
              console.error('loadJoinedGroups错误：群聊缺少有效的ID', group);
              return group;
            }
            
            const avatarMembers = await dispatch('fetchGroupAvatar', groupId);
            console.log("加入的群: ", group);
            
            return {
              id: groupId.toString(),
              username: group.name || '未命名群聊',
              photo: group.photo || null,
              target_id: groupId.toString(),
              created_at: group.created_at || new Date().toISOString(),
              unreadCount: group.unread_count || 0,
              members: group.members || [],
              membersCount: group.members_count || (group.members?.length || 0),
              ownerId: group.creator_id || null,
              avatar_members: avatarMembers // 添加头像成员列表
            };
          })
        );
        
        commit('INIT_JOINED_GROUPS', groupsWithAvatars);
        return groupsWithAvatars;
      } catch (error) {
        console.error('加载已加入的群聊失败:', error);
        ElMessage.error('加载已加入的群聊失败，请重试');
        return [];
      }
    },
    
    // 刷新单个群聊信息（不自动添加到最近聊天）
    async refreshJoinedGroup({ commit, rootState }, groupId) {
      try {
        if (!rootState.user?.id) {
          console.log('用户未登录，无法刷新群聊信息');
          return null;
        }
        
        // 确保groupId是有效的
        const groupIdStr = groupId.toString();
        
        const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${groupIdStr}`, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        if (response.data) {
          const updatedGroup = {
            id: groupIdStr,
            ...response.data,
            isGroup: true
          };
          
          commit('UPDATE_JOINED_GROUP', updatedGroup);
          return updatedGroup;
        }
      } catch (error) {
        console.error(`刷新群聊 ${groupId} 信息失败:`, error);
        ElMessage.error('刷新群聊信息失败');
        return null;
      }
    },
    
    // 保存最近聊天
    async saveRecentChat({ rootState, getters }, chatInfo) {
      try {
        if (!rootState.user?.id) {
          console.log('用户未登录，无法保存最近聊天记录');
          return;
        }
        
        if (!chatInfo) {
          console.error('saveRecentChat 错误：未提供聊天用户信息');
          return;
        }
        console.log("从保存最近聊天获取聊天信息：", chatInfo);
        
        const isGroup = chatInfo.isGroup === true;
        
        // 确保chatInfo有有效的id
        const chatId = chatInfo.id || chatInfo.group_id || chatInfo.target_id;
        if (!chatId) {
          console.error('saveRecentChat 错误：缺少有效的ID', chatInfo);
          return;
        }
        
        const chatIdStr = chatId.toString();
        
        // 对于群聊，先从已加入群聊中获取完整信息
        let fullChatInfo = { ...chatInfo, id: chatIdStr };
        if (isGroup) {
          const joinedGroup = getters.getJoinedGroupById(chatIdStr);
          if (joinedGroup) {
            fullChatInfo = { ...joinedGroup, ...chatInfo, id: chatIdStr };
          }
        }
        console.log("获取组合的信息：", rootState.user);
        console.log("获取聊天信息：", fullChatInfo);
        
        const recentChatData = {
          id: chatIdStr,
          user_id: rootState.user.id,
          target_id: chatIdStr,
          target_username: fullChatInfo.username,
          target_photo: fullChatInfo.photo,
          last_message: fullChatInfo.lastMessage || '',
          last_message_time: fullChatInfo.lastMessageTime || new Date().toISOString(),
          unread_count: fullChatInfo.unreadCount || 0,
          is_group: isGroup,
          ...(isGroup ? { members: fullChatInfo.members || [] } : {})
        };
        console.log("post： recentChat: ", recentChatData);
        
        await axios.post(`${API_CONFIG.BASE_URL}/ws/chat/recent-chats`, recentChatData, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
      } catch (error) {
        console.error('保存最近聊天记录失败:', error);
        throw error;
      }
    },
    
    // 清除未读计数
    async clearUnreadCount({ commit, rootState }, targetId) {
      try {
        const userId = rootState.user.id;
        
        // 确保targetId是有效的
        const targetIdStr = targetId.toString();
        
        await axios.post(
          `${API_CONFIG.BASE_URL}/ws/chat/recent-chats/${userId}/clear-unread/${targetIdStr}`, 
          {}, 
          { headers: { Authorization: `Bearer ${rootState.token}` } }
        );
        
        commit('UPDATE_UNREAD_COUNT', { targetId: targetIdStr, count: 0 });
      } catch (error) {
        console.error('清除未读计数失败:', error);
        throw error;
      }
    },
    
    // 登出时清除所有聊天记录
    async clearAllChats({ commit }) {
      commit('CLEAR_ALL_CHATS');
    },
    
    // 手动添加群聊到最近聊天（只有用户主动发起聊天时调用）
    async addGroupToRecent({ commit, dispatch }, groupInfo) {
      // 确保groupInfo有有效的id
      const groupId = groupInfo.id || groupInfo.group_id || groupInfo.target_id;
      if (!groupId) {
        console.error('addGroupToRecent 错误：缺少有效的ID', groupInfo);
        return;
      }
      
      const groupInfoWithId = { ...groupInfo, id: groupId.toString() };
      
      commit('ADD_RECENT_CHAT', groupInfoWithId);
      console.log("加入最近聊天：", groupInfoWithId);
      await dispatch('saveRecentChat', groupInfoWithId);
    }
  },
  getters: {
    getRecentChats: state => state.recentChats,
    getRecentGroups: state => state.recentGroups,
    getRecentUsers: state => state.recentUsers,
    getJoinedGroups: state => state.joinedGroups,
    
    getChatById: state => (id) => {
      const idStr = id.toString();
      return state.recentChats.find(chat => chat.id.toString() === idStr);
    },
    
    getJoinedGroupById: state => (id) => {
      const idStr = id.toString();
      return state.joinedGroups.find(group => group.id.toString() === idStr);
    },
    
    getTotalUnreadCount: state => {
      return state.recentChats.reduce((total, chat) => total + (chat.unreadCount || 0), 0);
    },
    
    getJoinedGroupsCount: state => state.joinedGroups.length
  }
};

// 辅助函数：更新合并的聊天列表
function updateCombinedChats(state) {
  const allChats = [...state.recentGroups, ...state.recentUsers];
  allChats.sort((a, b) => {
    const timeA = a.lastMessageTime ? new Date(a.lastMessageTime) : new Date(0);
    const timeB = b.lastMessageTime ? new Date(b.lastMessageTime) : new Date(0);
    return timeB - timeA;
  });
  state.recentChats = allChats.slice(0, 50);
}

export default chatModule;
